from taf.ul.ettf.context import context
from taf.ul.ettf.scheduler.base_listeners import SuiteListener


class robot_context(SuiteListener):
    def __init__(self):
        super(robot_context, self).__init__(always_on=True)

    def start_suite(self, suite, result):
        context.set_suite_name(suite.name)

    def start_test(self, test, result):
        context.set_test_name(test.name)
